import mock

from testsuite.Ulm.ET.Performance_Test.resources.python import taf_sw_wtssim_wrapper


def test_execute_egate_command_retries_on_alias_lookup_error():
    """Generated by AI: 2026-04-07 - Alias lookup retry unit test."""
    alias_error = taf_sw_wtssim_wrapper.taf.internal.aliasing.AliasLookupError(
        "alias not found"
    )
    sw_wtssim_obj = mock.Mock()
    sw_wtssim_obj.execute_egate_command.side_effect = [alias_error, "ok"]

    with mock.patch(
            'testsuite.Ulm.ET.Performance_Test.resources.python.taf_sw_wtssim_wrapper.get_taf_sw_wtssim_obj',
            return_value=sw_wtssim_obj), mock.patch(
                'testsuite.Ulm.ET.Performance_Test.resources.python.'
                'taf_sw_wtssim_wrapper.'
                'setup_all_egates_and_edaemons_connections') as setup_mock:
        output = taf_sw_wtssim_wrapper.execute_egate_command(
            'sim_log_set',
            test_pc_index=0,
            max_retries=2
        )

    assert output == "ok"
    assert sw_wtssim_obj.execute_egate_command.call_count == 2
    setup_mock.assert_called_once()
